)

var ErrLimit = errors.New("лимит исчерпан")

func withdraw(amount int) error {
    if amount > 100 {
        return fmt.Errorf("снятие %d: %w", amount, ErrLimit)
    }
    return nil
}

func main() {
    err := withdraw(150)
    fmt.Println(errors.Is(err, ErrLimit))
