package main

import (
    "errors"
    "fmt"
)

type QuotaError struct {
    Used, Limit int
}

func (e QuotaError) Error() string {
    return fmt.Sprintf("квота: %d из %d", e.Used, e.Limit)
}

func main() {
    var err error = fmt.Errorf("загрузка: %w", QuotaError{Used: 12, Limit: 10})
    var qe QuotaError
    if errors.As(err, &qe) {
        fmt.Println(qe.Limit)
    }
    fmt.Println(err)
}
